const responseRaw = $input.first().json.message.content;
let data;

try {
  data = JSON.parse(responseRaw);
} catch (e) {
  // Mengatasi jika ada markdown codeblock ```json
  const cleanJson = responseRaw.replace(/```json/g, '').replace(/```/g, '').trim();
  data = JSON.parse(cleanJson);
}

return {
  json: {
    tanggal: data.tanggal,
    kategori: data.kategori,
    keterangan: data.keterangan,
    nominal: Number(data.nominal),
    pesan_mentah: $('Telegram Trigger').item.json.message.text,
    chat_id: $('Telegram Trigger').item.json.message.chat.id
  }
};
